11	use App\Ordering\Domain\ValueObject\CustomerId;
12	use App\Ordering\Domain\ValueObject\OrderId;
13	use App\Ordering\Domain\ValueObject\OrderStatus;
14	use App\SharedKernel\Domain\Currency;
15	use App\SharedKernel\Domain\Money;
16	use App\Tests\Support\Catalog;
17	use App\Tests\Support\TestDatabase;
18	use Doctrine\DBAL\Connection;
19	use Doctrine\ORM\EntityManagerInterface;
20	use PHPUnit\Framework\Attributes\Test;
21	use Symfony\Bundle\FrameworkBundle\KernelBrowser;
22	use Symfony\Bundle\FrameworkBundle\Test\WebTestCase;
23	
24	final class CancelOrderTest extends WebTestCase
25	{
26	    private KernelBrowser $client;
27	
28	    protected function setUp(): void
29	    {
30	        TestDatabase::reset();
31	        $GLOBALS['db'] = null;
32	        $this->client = self::createClient();
33	        $this->client->disableReboot();
34	        Catalog::seed(self::getContainer()->get(Connection::class));
35	        $this->client->loginUser(
36	            self::getContainer()->get(DemoCustomerProvider::class)->loadUserByIdentifier('sprava@example.com'),
37	        );
38	    }
39	
40	    #[Test]
41	    public function orderCanBeCancelledFromLegacyAdmin(): void
42	    {
43	        $orders = self::getContainer()->get(OrderRepository::class);
44	        $stockItems = self::getContainer()->get(StockItemRepository::class);
45	        $keyboard = \App\Ordering\Domain\ValueObject\ProductId::fromString(Catalog::KEYBOARD);
46	
47	        $order = Order::place(OrderId::generate(), CustomerId::generate());
48	        $order->addItem($keyboard, 2, new Money(300_00, Currency::CZK));
49	        $order->confirm();
50	        $orders->save($order);
51	
52	        $available = $stockItems->get($keyboard)->available();
53	
54	        $crawler = $this->client->request('GET', '/admin/legacy/order_edit?id=' . $order->id->value);
55	        $form = $crawler->selectButton('Uložit')->form();
56	        $form['status'] = 'cancelled';
57	        // CSRF token by měl být automaticky extrahován z formuláře
58	        $this->client->submit($form);
59	
60	        self::assertResponseIsSuccessful();
61	        self::assertSelectorTextContains('p.msg', 'stornována');
62	        self::getContainer()->get(EntityManagerInterface::class)->clear();
63	        $cancelled = $orders->get($order->id);
64	        self::assertSame(OrderStatus::Cancelled, $cancelled->status);
65	
66	        $newAvailable = $stockItems->get($keyboard)->available();
67	        self::assertSame($available + 2, $newAvailable);
68	    }
69	}
